    for number in numbers:

        if number > 5:

            if number % 2 == 0:
                result.append(number * 2)

            else:
                result.append(number + 1)

    return result

numbers = list(range(30))
result = analyze_numbers(numbers)
print(result)

def classify(numbers):

    result = []

    for number in numbers:

        if number > 10:
            if number > 20:
                if number > 30:
                    if number > 40:
                        if number > 50:
                            result.append(
                                "very-large"
                            )

    return result

numbers = list(range(4))
result = classify(numbers)
print(result)

def search(numbers, target):

    for number in numbers:

        if number == target:
            return True

    return False

